import { scoreArmy, type Card } from "./sphinx-score.js";

const readStdin = async (): Promise<string> => {
  const chunks: Buffer[] = [];
  for await (const chunk of process.stdin) chunks.push(chunk as Buffer);
  return Buffer.concat(chunks).toString("utf8");
};

// The JSON document this CLI reads from stdin.
type ArmyDocument = {
  army: Card[];
};

const document = JSON.parse(await readStdin()) as ArmyDocument;

process.stdout.write(JSON.stringify({ score: scoreArmy(document.army) }));
